CREATE TABLE local_runtime_sessions (
  session_id TEXT PRIMARY KEY,
  record_json TEXT NOT NULL,
  updated_at_ms INTEGER NOT NULL,
  columnar_version INTEGER NOT NULL DEFAULT 0,
  agent_name TEXT,
  runtime TEXT,
  session_type TEXT,
  status TEXT,
  archived INTEGER NOT NULL DEFAULT 0,
  visibility TEXT NOT NULL DEFAULT 'visible',
  session_kind TEXT NOT NULL DEFAULT 'unknown' CHECK (session_kind IN ('conversation', 'task', 'peek', 'channel', 'cron', 'unknown')),
  purpose TEXT,
  purpose_kind TEXT NOT NULL DEFAULT '',
  origin_cron_id TEXT,
  parent_session_id TEXT,
  workspace_dir TEXT,
  project_workspace_dir TEXT,
  is_default_workspace INTEGER NOT NULL DEFAULT 0 CHECK (is_default_workspace IN (0, 1)),
  title TEXT,
  created_at_ms INTEGER,
  error_message TEXT,
  error_code INTEGER,
  extra_data_json TEXT NOT NULL DEFAULT '{}',
  project_id INTEGER,
  history_relative_dir TEXT
);
